import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const _=JSON.parse('{"title":"多板型、旋转与间距：不要只比较面积","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp2d/business-scenario.md","filePath":"zh-cn/frameworks/bpp2d/business-scenario.md"}'),o={name:"zh-cn/frameworks/bpp2d/business-scenario.md"};function i(h,t,s,l,n,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="多板型、旋转与间距-不要只比较面积" tabindex="-1">多板型、旋转与间距：不要只比较面积 <a class="header-anchor" href="#多板型、旋转与间距-不要只比较面积" aria-label="Permalink to &quot;多板型、旋转与间距：不要只比较面积&quot;">​</a></h1><p>完成<a href="./first-layout.html">第一次二维排样</a>后，用一个四件问题区分几何可行性、板材消耗和费用。以下用新输入替换第一课的物品与板型。</p><h2 id="_1-两种板材与一个矩形零件" tabindex="-1">1. 两种板材与一个矩形零件 <a class="header-anchor" href="#_1-两种板材与一个矩形零件" aria-label="Permalink to &quot;1. 两种板材与一个矩形零件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>尺寸 / 数量</th><th style="text-align:right;">单价</th></tr></thead><tbody><tr><td>R</td><td>2 × 2 m，共 4 件</td><td style="text-align:right;">—</td></tr><tr><td>S</td><td>4 × 4 m，供给至少 1 张</td><td style="text-align:right;">5</td></tr><tr><td>L</td><td>5 × 5 m，供给至少 1 张</td><td style="text-align:right;">3</td></tr></tbody></table><p>承重充分，先禁止旋转、间距为零。S 可按 2×2 网格恰好放下四件，L 也能放下。以面积消耗为唯一目标会偏好 S（16 m²），以采购费用为唯一目标会偏好 L（3）。最少板数无法区分它们。</p><p>然后设相邻件间距为 0.2 m：每行两件需要 <code>2 + 0.2 + 2 = 4.2 m</code>，S 不再容纳这个 2×2 排布，L 仍能容纳。不能因为需求总面积仍为 16 m² 就断言 S 可行；对于四个轴对齐的 2×2 正方形，4×4 板也没有其他带正间距的四件排布。</p><h2 id="_2-把所有板型传入生成请求" tabindex="-1">2. 把所有板型传入生成请求 <a class="header-anchor" href="#_2-把所有板型传入生成请求" aria-label="Permalink to &quot;2. 把所有板型传入生成请求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>责任</th><th>Kotlin</th><th>Rust</th></tr></thead><tbody><tr><td>多板型请求</td><td><code>Bpp2dLayerGenerationRequest.sheets</code></td><td><code>Bpp2dLayerGenerationRequest</code> 的板型集合</td></tr><tr><td>候选身份</td><td><code>Layer.sheet</code> 保留类型</td><td>每个候选保留实际板型</td></tr><tr><td>间距</td><td>生成请求的 <code>kerf</code></td><td>请求的 <code>with_kerf(...)</code></td></tr><tr><td>目标</td><td>面积、数量、按板型费用的建模管线</td><td>对应面积、数量、板型费用管线</td></tr></tbody></table><p><code>sheet</code> 的默认/主板型不替代 <code>sheets</code> 的完整集合。同一物品坐标放到 S、L 上是两种列，不能只按坐标去重。</p><p>沿用第一课的物品构造方式，构造 S、L 两种 <code>SheetType</code> 并一起传入请求。费用目标还需进入主问题配置，不能仅在输出表中附加单价。</p><h2 id="_3-单独验证间距路径" tabindex="-1">3. 单独验证间距路径 <a class="header-anchor" href="#_3-单独验证间距路径" aria-label="Permalink to &quot;3. 单独验证间距路径&quot;">​</a></h2><p>改变间距后重新生成候选并求解，再逐件计算实际边界间距；只看到候选数量下降，不能证明所有放置间距都合法。</p><h2 id="_4-再做一个旋转对照" tabindex="-1">4. 再做一个旋转对照 <a class="header-anchor" href="#_4-再做一个旋转对照" aria-label="Permalink to &quot;4. 再做一个旋转对照&quot;">​</a></h2><p>把问题单独改为一张 <code>3 × 2 m</code> 板和一件 <code>2 × 3 m</code> 零件，间距为零。允许 90° 旋转时可放，禁止时不可放。这样可以隔离测试 <code>allowRotate</code>，避免使用正方形却误以为自己验证了旋转。</p><h2 id="_5-加入业务后怎样验收" tabindex="-1">5. 加入业务后怎样验收？ <a class="header-anchor" href="#_5-加入业务后怎样验收" aria-label="Permalink to &quot;5. 加入业务后怎样验收？&quot;">​</a></h2><ul><li>零间距面积目标选 S，费用目标选 L；若采用加权和，按配置重算总分，不能继续要求两个单目标结论。</li><li>间距改变后重新生成候选、求解和复核；只在图上挪坐标不算接入规则。</li><li>多板型库存/采购限制只有真正进入主问题才有效；不要把输入目录中的板型数量当作已建模库存。</li><li>净物品面积、板材消耗、空闲区域和可回用余料分开报告；可回用还需要最小宽高等业务标准。</li></ul><p>需要断头台裁切树时继续 <a href="./../csp2d/business-scenario.html">CSP2D 工艺场景</a>，不是给 BPP2D 排布改一个名字。将结果接入业务前完成<a href="./../integration.html">公共接入检查</a>。</p><p>源码回归命令统一放在<a href="./../verification.html">仓库验证参考</a>；先完成业务输入、调用与结果复核，再按需验证。</p>',18)])])}const m=e(o,[["render",i]]);export{_ as __pageData,m as default};
